CREATE DATABASE IF NOT EXISTS agjencia_turistike CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE agjencia_turistike;
CREATE TABLE IF NOT EXISTS rolet (id INT AUTO_INCREMENT PRIMARY KEY, emri VARCHAR(50) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS perdoruesit (id INT AUTO_INCREMENT PRIMARY KEY, emri VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, fjalekalimi VARCHAR(255) NOT NULL, roli_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_user_role FOREIGN KEY(roli_id) REFERENCES rolet(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS destinacionet (id INT AUTO_INCREMENT PRIMARY KEY, emri VARCHAR(120) NOT NULL, shteti VARCHAR(120) NOT NULL, pershkrimi TEXT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ofertat (id INT AUTO_INCREMENT PRIMARY KEY, destinacioni_id INT NOT NULL, titulli VARCHAR(160) NOT NULL, pershkrimi TEXT, cmimi DECIMAL(10,2) NOT NULL, data_nisjes DATE NOT NULL, data_kthimit DATE NOT NULL, vende INT NOT NULL DEFAULT 20, CONSTRAINT fk_offer_dest FOREIGN KEY(destinacioni_id) REFERENCES destinacionet(id) ON DELETE RESTRICT, CONSTRAINT chk_cmimi CHECK (cmimi >= 0), CONSTRAINT chk_vende CHECK (vende >= 0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rezervimet (id INT AUTO_INCREMENT PRIMARY KEY, perdoruesi_id INT NOT NULL, oferta_id INT NOT NULL, numri_personave INT NOT NULL, data_rezervimit DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, statusi ENUM('Ne pritje','Konfirmuar','Anuluar') NOT NULL DEFAULT 'Ne pritje', CONSTRAINT fk_booking_user FOREIGN KEY(perdoruesi_id) REFERENCES perdoruesit(id) ON DELETE RESTRICT, CONSTRAINT fk_booking_offer FOREIGN KEY(oferta_id) REFERENCES ofertat(id) ON DELETE RESTRICT, CONSTRAINT chk_persona CHECK(numri_personave > 0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pagesat (id INT AUTO_INCREMENT PRIMARY KEY, rezervimi_id INT NOT NULL, shuma DECIMAL(10,2) NOT NULL, metoda VARCHAR(50) NOT NULL, statusi ENUM('Ne pritje','Paguar','Deshtuar') NOT NULL DEFAULT 'Ne pritje', data_pageses DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_payment_booking FOREIGN KEY(rezervimi_id) REFERENCES rezervimet(id) ON DELETE RESTRICT, CONSTRAINT chk_shuma CHECK(shuma >= 0)) ENGINE=InnoDB;
INSERT IGNORE INTO rolet (id,emri) VALUES (1,'Administrator'),(2,'Staf'),(3,'Klient');
